CREATE TABLE files(path TEXT PRIMARY KEY, size INTEGER NOT NULL, mtime TEXT NOT NULL, sha256 TEXT NOT NULL, kind TEXT NOT NULL, seen INTEGER NOT NULL);
CREATE TABLE modules(id TEXT PRIMARY KEY, path TEXT UNIQUE NOT NULL REFERENCES files(path) ON DELETE CASCADE, hash TEXT NOT NULL, kind TEXT NOT NULL, entry_point INTEGER NOT NULL, parser_version INTEGER NOT NULL, decoder_version INTEGER NOT NULL, cfg_version INTEGER NOT NULL, dataflow_version INTEGER NOT NULL, status TEXT NOT NULL, provenance TEXT NOT NULL DEFAULT 'REAL');
CREATE TABLE sections(module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, idx INTEGER NOT NULL, name TEXT NOT NULL, kind INTEGER NOT NULL, flags INTEGER NOT NULL, address INTEGER NOT NULL, size INTEGER NOT NULL, file_offset INTEGER NOT NULL, file_size INTEGER NOT NULL, PRIMARY KEY(module,idx));
CREATE TABLE imports(module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, section INTEGER NOT NULL, library TEXT NOT NULL, entry_count INTEGER NOT NULL, signature INTEGER NOT NULL, is_code INTEGER NOT NULL, PRIMARY KEY(module,section));
CREATE TABLE exports(module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, section INTEGER NOT NULL, name TEXT NOT NULL, address INTEGER NOT NULL, is_code INTEGER NOT NULL);
CREATE TABLE symbols(module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, symbol_table INTEGER NOT NULL, idx INTEGER NOT NULL, name TEXT NOT NULL, address INTEGER NOT NULL, size INTEGER NOT NULL, info INTEGER NOT NULL, section INTEGER NOT NULL, PRIMARY KEY(module,symbol_table,idx));
CREATE TABLE relocations(module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, section INTEGER NOT NULL, target_section INTEGER NOT NULL, symbol_table INTEGER NOT NULL, offset INTEGER NOT NULL, kind INTEGER NOT NULL, symbol INTEGER NOT NULL, addend INTEGER);
CREATE INDEX relocation_source ON relocations(module,offset);
CREATE TABLE analysis_runs(id INTEGER PRIMARY KEY, status TEXT NOT NULL, started TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, finished TEXT, modules_done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE functions(id TEXT PRIMARY KEY, module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, address INTEGER NOT NULL, name TEXT, status TEXT NOT NULL, provenance TEXT NOT NULL DEFAULT 'INFERRED', UNIQUE(module,address));
CREATE TABLE function_evidence(function TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, kind TEXT NOT NULL, source INTEGER NOT NULL, provenance TEXT NOT NULL, PRIMARY KEY(function,kind,source));
CREATE TABLE instructions(module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, address INTEGER NOT NULL, raw INTEGER NOT NULL, opcode TEXT NOT NULL, status TEXT NOT NULL, classification TEXT NOT NULL, operands TEXT NOT NULL, semantics TEXT NOT NULL, control_flow TEXT NOT NULL, PRIMARY KEY(module,address));
CREATE TABLE function_instructions(function TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, address INTEGER NOT NULL, PRIMARY KEY(function,address));
CREATE TABLE basic_blocks(function TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, start INTEGER NOT NULL, end INTEGER NOT NULL, PRIMARY KEY(function,start));
CREATE TABLE cfg_edges(function TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, source INTEGER NOT NULL, target INTEGER, kind TEXT NOT NULL);
CREATE TABLE call_sites(function TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, address INTEGER NOT NULL, kind TEXT NOT NULL, target INTEGER, evidence TEXT NOT NULL, PRIMARY KEY(function,address));
CREATE TABLE call_edges(caller TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, callee TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, address INTEGER NOT NULL, PRIMARY KEY(caller,callee,address));
CREATE TABLE cross_references(module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, source INTEGER NOT NULL, target INTEGER, kind TEXT NOT NULL, provenance TEXT NOT NULL);
CREATE INDEX xref_target ON cross_references(target);
CREATE INDEX xref_source ON cross_references(source);
CREATE TABLE indirect_sites(function TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, address INTEGER NOT NULL, status TEXT NOT NULL, target INTEGER, evidence TEXT NOT NULL, PRIMARY KEY(function,address));
CREATE TABLE block_liveness(function TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, block INTEGER NOT NULL, live_in TEXT NOT NULL, live_out TEXT NOT NULL, PRIMARY KEY(function,block));
CREATE TABLE unknown_opcodes(module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, opcode INTEGER NOT NULL, extended_opcode INTEGER NOT NULL, count INTEGER NOT NULL, example INTEGER NOT NULL, PRIMARY KEY(module,opcode,extended_opcode));
CREATE TABLE jump_tables(id TEXT PRIMARY KEY, module TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, address INTEGER NOT NULL, status TEXT NOT NULL, bound INTEGER, evidence TEXT NOT NULL);
CREATE TABLE jump_table_entries(table_id TEXT NOT NULL REFERENCES jump_tables(id) ON DELETE CASCADE, idx INTEGER NOT NULL, target INTEGER NOT NULL, PRIMARY KEY(table_id,idx));
CREATE TABLE problems(id INTEGER PRIMARY KEY, module TEXT REFERENCES modules(id) ON DELETE CASCADE, function TEXT REFERENCES functions(id) ON DELETE CASCADE, address INTEGER, category TEXT NOT NULL, summary TEXT NOT NULL, provenance TEXT NOT NULL);
CREATE TABLE ai_jobs(id INTEGER PRIMARY KEY, function TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, cache_key TEXT UNIQUE NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, status TEXT NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_findings(id INTEGER PRIMARY KEY, job INTEGER UNIQUE NOT NULL REFERENCES ai_jobs(id) ON DELETE CASCADE, function TEXT NOT NULL REFERENCES functions(id) ON DELETE CASCADE, category TEXT NOT NULL, summary TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence >= 0 AND confidence <= 1), provenance TEXT NOT NULL CHECK(provenance = 'AI_PROPOSED'));
CREATE TABLE ai_finding_evidence(finding INTEGER NOT NULL REFERENCES ai_findings(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL, description TEXT NOT NULL, PRIMARY KEY(finding,ordinal));
CREATE TABLE ai_hypotheses(id INTEGER PRIMARY KEY, finding INTEGER NOT NULL REFERENCES ai_findings(id) ON DELETE CASCADE, target TEXT NOT NULL, hypothesis TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'UNPROVEN');
